/**
 * One animation clip. `animation` selects the first clip of that `name`, or else the clip at that
 * `index`.
 */
export interface AnimationInfo {
  /** Seconds from the start to the last key of any channel, morph target weights' included. */
  readonly duration: number;
  readonly index: number;
  /** Absent when the file doesn't name the clip. */
  readonly name?: string;
}

/** What an asset holds, which its store knows from checking it. */
export type AssetKind = "image" | "video" | "audio" | "font" | "model" | "environment" | "lut";

/** What the mixer plays: the voices, and the segments of root samples each plays. */
export interface AudioPlan {
  readonly segments: readonly AudioSegment[];
  readonly voices: readonly AudioVoice[];
}

/**
 * Root samples `start + i` for `i` in `0..frames`, where a voice plays its clip at
 * `position + step * i` samples from the clip's start, at a gain moving linearly from `gain[0]`
 * at `i = 0` to `gain[1]` at `i = frames`. Only positions in `[from, to)` sound: the clip, cut
 * by the windows of the `clip` nodes that play it.
 */
export interface AudioSegment {
  readonly frames: number;
  readonly from: number;
  readonly gain: readonly [number, number];
  readonly position: number;
  readonly start: number;
  readonly step: number;
  readonly to: number;
  readonly voice: number;
}

/**
 * An audio clip as one instance plays it: a clip of the root's timeline, or of a template's for
 * one path of `clip` nodes that plays the template.
 */
export interface AudioVoice {
  /** The clip's length and its fades, in samples of the composition the clip is in. */
  readonly duration: number;
  readonly fadeIn: number;
  readonly fadeOut: number;
  readonly sourceId: string;
  /** The source sample at the clip's start. */
  readonly sourceStart: number;
}

/**
 * One camera. `camera` selects the first camera of that `name`, or else the camera at that
 * `index`.
 */
export interface CameraInfo {
  readonly index: number;
  /** Absent when the file doesn't name the camera. */
  readonly name?: string;
}

/**
 * A problem the engine found with a composition. Its `code` is stable and public, and new codes
 * can appear in any release, so treat one you don't know by its severity.
 */
export interface Diagnostic {
  /**
   * Stable and public, such as `node.unknown_param` or `font.fallback`. New codes can appear in
   * any release.
   */
  readonly code: DiagnosticCode;
  /** Free-form text for people to read, which can change in any release. */
  readonly message: string;
  /** The node the diagnostic is about, in the graph `path` points into. */
  readonly node?: number;
  /**
   * A JSON pointer into the composition, such as `/nodes/3/params/opacity`. Empty for the
   * whole document.
   */
  readonly path: string;
  readonly severity: Severity;
}

/** A media param set by an expression, whose source is known only when a frame evaluates it. */
export interface DynamicMediaUse {
  readonly kinds: readonly AssetKind[];
  readonly node: number;
  /** The param's path in the node's `params`, such as `source` or `content[1].font_family`. */
  readonly param: string;
  /** The template the node is in, absent for the root. */
  readonly template?: string;
}

/** Which param of which node to evaluate, and when. */
export interface EvaluateRequest {
  /**
   * The composition frame, which may be fractional. A node inside a `clip`, or behind a
   * `time_remap`, is evaluated at the frame of its own time that this frame maps to.
   */
  readonly frame: number;
  /**
   * The copy an `instance_3d`'s `position`, `rotation` and `scale` are evaluated for, which
   * they read as `instance`. Other nodes and params ignore it.
   */
  readonly instance?: number;
  /** A node of the root composition. */
  readonly node: number;
  /**
   * The param's name in the node's `params`. A group of params the node flattens, such as
   * `position`, is addressed by the names it flattens to.
   */
  readonly param: string;
}

/**
 * A font family a text node names as a literal. A family is not a media source: the host
 * resolves it by name, falling back to its own fonts, unless it is written `asset:<id>`.
 */
export interface FontDependency {
  readonly family: string;
  readonly uses: readonly NodeParamAt[];
}

/** The images and video frames one frame of the composition reads. */
export interface FrameRequirements {
  /** The ids of the images, in order and without repeats. */
  readonly images: readonly string[];
  readonly videos: readonly VideoFrameRequirement[];
}

/**
 * One material. `texture_material` selects the first material of that `name`; an unnamed material
 * can't be selected.
 */
export interface MaterialInfo {
  /** Whether a texture multiplies its base colour, which a `texture` input replaces. */
  readonly hasBaseColorTexture: boolean;
  readonly index: number;
  /** Absent when the file doesn't name the material. */
  readonly name?: string;
}

/**
 * A source the composition names as written (a path, a URL or an alias, or `asset:<id>`), with
 * each place it is used.
 */
export interface MediaDependency {
  /** The kinds of media the uses read, without repeats, in the order the uses first name them. */
  readonly kinds: readonly AssetKind[];
  readonly source: string;
  readonly uses: readonly MediaUse[];
}

export type MediaFailureCode = "media.not_found" | "media.wrong_kind" | "media.unsupported" | "media.too_large" | "media.decode";

/** A media source that can't be used, the same way for every kind and every host. */
export interface MediaFailure {
  /** For `media.too_large`, the value over the limit, when it is known. */
  readonly actual?: number;
  /** Where the composition uses the source, when known. */
  readonly at?: MediaLocation;
  /**
   * Why the source can't be used, as its public diagnostic code. `media.decode` is data that should be
   * what the use reads but is corrupt, truncated or in no format the engine identifies;
   * `media.unsupported` is data it identifies and doesn't read, such as a codec it lacks.
   */
  readonly code: MediaFailureCode;
  readonly details: string;
  /**
   * The kind the source is, when that is established. It is absent when it can't be told,
   * such as an MP4 that is not video-only or audio-only until opened.
   */
  readonly found?: AssetKind;
  /** For `media.too_large`, the limit, in the unit `details` names. */
  readonly limit?: number;
  /** The source as the composition wrote it: a path, URL, alias or `asset:<id>`. */
  readonly source: string;
  /** The kinds the place using the source reads; empty when the host that failed doesn't know. */
  readonly wanted: readonly AssetKind[];
}

/** Everything a composition needs before it renders, found without rendering it. */
export interface MediaInventory {
  readonly dynamic: readonly DynamicMediaUse[];
  readonly fonts: readonly FontDependency[];
  /**
   * Each distinct source, in the order the root's nodes, the templates' nodes and then the
   * audio first name it.
   */
  readonly media: readonly MediaDependency[];
}

/** Where a composition names a source. */
export type MediaLocation = (NodeParamAt & {
  readonly type: "node";
}) | {
  readonly clip: string;
  /** The clip's position in the timeline's `clips`. */
  readonly index: number;
  readonly template?: string;
  readonly track: string;
  readonly type: "audioClip";
};

/** One place a source is used, and the kinds of media it reads there. */
export interface MediaUse {
  readonly at: MediaLocation;
  readonly kinds: readonly AssetKind[];
}

/**
 * What a model offers a `model_3d` node to choose from: the clips `animation` names, the
 * materials `texture_material` names and the cameras `camera` names.
 */
export interface ModelInfo {
  readonly animations: readonly AnimationInfo[];
  readonly cameras: readonly CameraInfo[];
  readonly materials: readonly MaterialInfo[];
}

/** A param of a node, in the root composition or in a template. */
export interface NodeParamAt {
  readonly node: number;
  /** The param's path in the node's `params`, such as `source` or `content[1].font_family`. */
  readonly param: string;
  /** The template the node is in, absent for the root. */
  readonly template?: string;
}

/** Whether a diagnostic stops a composition rendering. */
export type Severity = "error" | "warning";

/** The frames of one video stream a frame reads. */
export interface VideoFrameRequirement {
  /** The frame numbers in the video, ascending. */
  readonly frames: readonly number[];
  readonly streamId: string;
}
